import { generateText } from 'ai';
import { model } from '../helpers/selected-model.js';

export async function getMessageFromModelWithTrace() {
  let steps = 0;
  let totalTokens = 0;
  let usageAvailable = true;

  const { text } = await generateText({
    model,
    prompt: 'Responde solamente con: "OK, todo listo!"',
    onStepEnd({ usage, toolCalls, toolResults }) {
      steps += 1;
      if (usage.totalTokens === undefined) usageAvailable = false;
      totalTokens += usage.totalTokens ?? 0;
      console.log('Paso:', steps);
      console.log('Herramientas solicitadas:', toolCalls.length);
      console.log('Resultados de herramientas:', toolResults.length);
    },
  });

  const summary = {
    steps,
    totalTokens: usageAvailable ? totalTokens : 'No disponible',
  };
  console.log('Respuesta:', text.trim());
  console.table(summary);
  return summary;
}

import { APICallError, generateText } from 'ai';
import { model } from '../helpers/selected-model.js';

export async function getMessageFromModelFailSafe() {
  try {
    const { text } = await generateText({
      model,
      prompt: 'Responde solamente con: "OK, todo listo!"',
    });
    console.log('Respuesta:', text.trim());
  } catch (error: unknown) {
    if (APICallError.isInstance(error)) {
      const status = error.statusCode;
      if (status === 401 || status === 403) {
        console.error('Revisa la credencial y sus permisos.');
      } else if (status === 429) {
        console.error('Revisa la cuota o el límite de solicitudes.');
      } else if (status === 404) {
        console.error('Revisa el modelo y la URL del proveedor.');
      } else if (status !== undefined && status >= 500) {
        console.error('El proveedor respondió con un error de servidor.');
      } else {
        console.error('La petición falló. Revisa su configuración.');
      }
    } else {
      console.error('No se completó la llamada. Revisa red y configuración.');
    }
    process.exitCode = 1;
  }
}
